using System.Text.Json;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using System.Windows.Threading;
namespace KarimEldamatyWindows;

/// Opt-in native verification runs only on Windows, against an isolated temporary library.
/// Captures are evidence for the computer that ran the checks, never for an untested release.
internal static class WindowsSelfTest
{
    public static async Task RunAsync(MainWindow window,string? outputPath)
    {
        var output=outputPath??Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),"Karim-Windows-Checks-"+DateTime.Now.ToString("yyyyMMdd-HHmmss"));Directory.CreateDirectory(output);var checks=new List<object>();
        async Task Check(string name,Func<Task> action){try{await action();checks.Add(new{name,passed=true});}catch(Exception ex){checks.Add(new{name,passed=false,error=ex.Message});}}
        await Check("home-light",async()=>{WindowsTheme.SetMode("Light");await Settle();File.WriteAllText(Path.Combine(output,"ui-scale.json"),JsonSerializer.Serialize(new{fontSize=window.FontSize,dpi=VisualTreeHelper.GetDpi(window).DpiScaleX,systemFontSize=SystemFonts.MessageFontSize}));Capture(window,Path.Combine(output,"home-light.png"));});
        var board=new Board{Title="Windows synthetic verification",Background="Square grid",Width=1600,Height=1000};
        for(var i=0;i<BrushSettings.PenNames.Length;i++){var name=BrushSettings.PenNames[i];board.Elements.Add(new(){Kind="stroke",Pen=name,BrushSettings=BrushSettings.Defaults(name),Color=InkColor.Palette[i%6],Points=Enumerable.Range(0,100).Select(n=>new InkPoint(120+n*5,80+i*70+15*Math.Sin(n*.09),Math.Clamp(.1+.9*n/99d,0,1)){TiltX=.4,TiltY=.2}).ToList()});}
        board.Elements.Add(new(){Kind="line",Points=[new(800,80),new(1380,230)],Width=3});board.Elements.Add(new(){Kind="text",Points=[new(800,270)],Text="Engineering: F = ma\nالعربية · editable text",FontSize=30});
        await Check("all-brushes-and-file-roundtrip",async()=>{await window.Store.SaveAsync(board);await window.OpenBoardAsync(board);if(window.Session.SelectedIds.Count!=0)throw new Exception("New drawing unexpectedly selected artwork.");var json=BoardCodec.Serialize(window.Session.Board);var read=BoardCodec.Deserialize(json);if(read.Elements.Count!=12)throw new Exception("Element count changed.");File.WriteAllText(Path.Combine(output,"synthetic.engboard"),json);await Settle();Capture(window,Path.Combine(output,"drawing-light.png"));});
        await Check("bilingual-text-export-visible",()=>{var fixture=new Board{Background="Plain",Width=1000,Height=300,Elements=[new(){Kind="text",Points=[new(50,40)],Text="SketchGlide ideas\nالعربية · editable text",FontSize=32,Color=InkColor.Graphite}]};var bitmap=BoardExport.RenderBitmap(fixture);var pixels=new byte[bitmap.PixelWidth*bitmap.PixelHeight*4];bitmap.CopyPixels(pixels,bitmap.PixelWidth*4,0);var inkPixels=Enumerable.Range(0,pixels.Length/4).Count(i=>pixels[i*4]<200&&pixels[i*4+1]<200&&pixels[i*4+2]<200);if(inkPixels<200)throw new Exception("Mixed English/Arabic text rendered outside the page.");File.WriteAllBytes(Path.Combine(output,"bilingual-text.png"),BoardExport.RenderPNG(fixture));File.WriteAllText(Path.Combine(output,"bilingual-text-result.json"),JsonSerializer.Serialize(new{inkPixels}));return Task.CompletedTask;});
        await Check("dark-workspace",async()=>{WindowsTheme.SetMode("Dark");window.ShowPanel("Tools");await Settle();Capture(window,Path.Combine(output,"drawing-dark.png"));});
        await Check("symbol-library-assets",async()=>{var defs=JsonSerializer.Deserialize<JsonElement[]>(File.ReadAllText(Path.Combine(AppContext.BaseDirectory,"Resources","SymbolCatalog.json")))!;if(defs.Length<380)throw new Exception("Symbol catalogue is incomplete.");foreach(var definition in defs){var id=definition.GetProperty("id").GetString()!;_=UI.Bitmap(Path.Combine(AppContext.BaseDirectory,"Resources","Symbols",id+".png"),100);}window.ShowPanel("Symbols");await Settle();Capture(window,Path.Combine(output,"symbols-dark.png"));});
        await Check("png-pdf-and-off-sheet-ink",()=>{var e=new DrawingElement{Kind="line",Points=[new(-300,500),new(-100,600)],Width=6};board.Elements.Add(e);BoardExport.ExportImage(board,Path.Combine(output,"drawing.png"));BoardExport.ExportPDF(board,Path.Combine(output,"drawing.pdf"));var bytes=File.ReadAllBytes(Path.Combine(output,"drawing.pdf"));if(bytes.Length<1000||System.Text.Encoding.ASCII.GetString(bytes,0,8)!="%PDF-1.4")throw new Exception("PDF header is invalid.");return Task.CompletedTask;});
        await Check("offline-maths-model",async()=>{List<InkPoint[]> samples=[[new(10,10),new(100,100)],[new(100,10),new(10,100)]];var matches=await MathRecognitionService.Shared.RecognizeAsync(samples,CancellationToken.None);if(matches.Count==0||matches.Any(m=>!double.IsFinite(m.Probability)))throw new Exception("Maths inference returned no candidates.");File.WriteAllText(Path.Combine(output,"maths-candidates.json"),JsonSerializer.Serialize(matches));});
        await Check("formula-editor",async()=>{foreach(var (name,latex) in new[]{("fraction",@"\frac{a+b}{2}"),("root",@"\sqrt{x^2+y^2}"),("integral",@"\int_0^1 x^2 dx")}){var png=FormulaRenderer.RenderPng(latex,InkColor.Graphite,32);if(png.Length<100)throw new Exception("Formula rendering returned no image.");File.WriteAllBytes(Path.Combine(output,"formula-"+name+".png"),png);}var w=new MathWindow(window.Session){Owner=window};w.Show();await Settle();Capture(w,Path.Combine(output,"maths-window.png"));w.Close();});
        await Check("3d-editor",async()=>{var w=new Sketch3DWindow(window.Session){Owner=window};w.Show();await Settle();var add=FindButton(w,"Box")??throw new Exception("3D Box control is missing.");add.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));await Settle();var viewport=FindVisual<System.Windows.Controls.Viewport3D>(w)??throw new Exception("3D viewport is missing.");var preview=new RenderTargetBitmap(Math.Max(1,(int)viewport.ActualWidth),Math.Max(1,(int)viewport.ActualHeight),96,96,PixelFormats.Pbgra32);preview.Render(viewport);var pixels=new byte[preview.PixelWidth*preview.PixelHeight*4];preview.CopyPixels(pixels,preview.PixelWidth*4,0);var renderedPixels=Enumerable.Range(0,pixels.Length/4).Count(i=>pixels[i*4+3]>100);File.WriteAllText(Path.Combine(output,"3d-render-diagnostics.json"),JsonSerializer.Serialize(new{width=viewport.ActualWidth,height=viewport.ActualHeight,tier=RenderCapability.Tier>>16,renderedPixels,sessionId=System.Diagnostics.Process.GetCurrentProcess().SessionId,camera=viewport.Camera?.ToString(),models=viewport.Children.OfType<System.Windows.Media.Media3D.ModelVisual3D>().Select(x=>x.Content?.Bounds.ToString()).ToArray()}));Capture(w,Path.Combine(output,"3d-window.png"));w.Close();if(renderedPixels<100)throw new Exception("3D geometry was not visible. Run the check in a logged-in Windows desktop session with graphics support.");});
        await Check("engineering-tools",async()=>{var w=new EngineeringWindow(window.Session){Owner=window};w.Show();await Settle();Capture(w,Path.Combine(output,"engineering-tools.png"));w.Close();});
        await Check("pressure-curves-and-frozen-brushes",()=>{foreach(var pen in BrushSettings.PenNames){var settings=BrushSettings.Defaults(pen);var low=settings.Width(0);var high=settings.Width(1);if(!double.IsFinite(low)||high<low||settings.Alpha(0)>settings.Alpha(1))throw new Exception("Pressure curve failed: "+pen);if(!InkColor.Teal.Brush().IsFrozen)throw new Exception("Colour brush is not frozen.");if(pen=="Technical Fineliner"&&low!=high)throw new Exception("Fineliner width changed with pressure.");}return Task.CompletedTask;});
        await Check("editable-selection-copy-paste-and-undo",()=>{var source=BoardCodec.Clone(board);source.Notes="PRIVATE SYNTHETIC NOTE";source.NotionURL="https://example.test/private";var ids=source.Elements.Take(2).Select(e=>e.Id).ToHashSet();var payload=SelectionCodec.Encode(source,ids);if(payload.Contains("PRIVATE SYNTHETIC NOTE")||payload.Contains("example.test/private"))throw new Exception("Copy leaked unrelated note metadata.");var target=new DrawingSession();var originalIDs=ids.ToArray();if(SelectionCodec.Paste(target,payload,200,150)!=2||target.SelectedIds.Overlaps(originalIDs))throw new Exception("Paste count or identifiers failed.");target.Undo();if(target.Board.Elements.Count!=0)throw new Exception("Paste Undo failed.");target.Redo();if(target.Board.Elements.Count!=2)throw new Exception("Paste Redo failed.");return Task.CompletedTask;});
        await Check("native-dpapi-isolated-roundtrip",()=>{const string name="synthetic-self-test";CredentialStore.Save(name,"synthetic-value-no-real-key");if(CredentialStore.Read(name)!="synthetic-value-no-real-key")throw new Exception("DPAPI roundtrip failed.");CredentialStore.Delete(name);if(CredentialStore.Read(name)!=null)throw new Exception("DPAPI synthetic value not removed.");return Task.CompletedTask;});
        await Check("offline-text-ocr-fixture",async()=>{var fixture=new Board{Background="Plain",Width=1000,Height=300,Elements=[new(){Kind="text",Points=[new(50,50)],Text="HELLO GLIDE",FontSize=72,Color=InkColor.Graphite}]};var png=BoardExport.RenderPNG(fixture);File.WriteAllBytes(Path.Combine(output,"ocr-fixture.png"),png);var result=await HandwritingRecognitionService.RecognizeAsync(png,CancellationToken.None);File.WriteAllText(Path.Combine(output,"ocr-fixture.json"),JsonSerializer.Serialize(result));if(!result.Text.Contains("GLIDE",StringComparison.OrdinalIgnoreCase))throw new Exception("Printed OCR fixture returned no expected word GLIDE. This check verifies local native inference, not perfect handwriting accuracy.");});
        await Check("scene-index-large-drawing-dirty-update",()=>{var drawing=new Board{Elements=Enumerable.Range(0,1200).Select(i=>new DrawingElement{Points=Enumerable.Range(0,40).Select(n=>new InkPoint(i*100+n,i*2)).ToList()}).ToList()};var index=new DocumentSceneIndex();index.Synchronize(drawing);var initial=index.GeometryRebuildCount;for(int i=0;i<10;i++)index.Synchronize(drawing);if(index.GeometryRebuildCount!=initial)throw new Exception("Unchanged drawing geometry rebuilt.");var visible=index.Query(new Rect(0,0,500,300));if(visible.Count>=drawing.Elements.Count||visible.Count==0)throw new Exception("Viewport culling failed.");drawing.Elements[10].Points[20].X+=2;index.Synchronize(drawing);if(index.GeometryRebuildCount!=initial+1)throw new Exception("Interior sample invalidation failed.");return Task.CompletedTask;});
        await Check("assistant-and-notes-interface",async()=>{window.ShowPanel("AI");await Settle();Capture(window,Path.Combine(output,"assistant-panel.png"));window.ShowPanel("Notes");await Settle();Capture(window,Path.Combine(output,"notes-panel.png"));});
        var passed=checks.All(x=>JsonSerializer.SerializeToElement(x).GetProperty("passed").GetBoolean());var report=new{passed,date=DateTimeOffset.Now,os=Environment.OSVersion.ToString(),architecture=System.Runtime.InteropServices.RuntimeInformation.ProcessArchitecture.ToString(),osArchitecture=System.Runtime.InteropServices.RuntimeInformation.OSArchitecture.ToString(),sessionId=System.Diagnostics.Process.GetCurrentProcess().SessionId,nativeWindowsRuntime=true,physicalTabletTested=false,liveOpenAIOrCraftTested=false,visualInspectionRequired=true,checks};File.WriteAllText(Path.Combine(output,"windows-runtime-results.json"),JsonSerializer.Serialize(report,new JsonSerializerOptions{WriteIndented=true}));if(!passed)throw new Exception("Some native Windows checks failed. See "+output);
    }
    private static T? FindVisual<T>(DependencyObject root) where T:DependencyObject{if(root is T value)return value;for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++){var match=FindVisual<T>(VisualTreeHelper.GetChild(root,i));if(match is not null)return match;}return null;}
    private static Button? FindButton(DependencyObject root,string label){if(root is Button b&&Equals(b.Content,label))return b;for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++){var match=FindButton(VisualTreeHelper.GetChild(root,i),label);if(match is not null)return match;}return null;}
    private static async Task Settle(){await Application.Current.Dispatcher.InvokeAsync(()=>{},DispatcherPriority.ApplicationIdle);await Task.Delay(180);}
    private static void Capture(Window window,string path){window.UpdateLayout();var target=window.Content as FrameworkElement??window;var dpi=VisualTreeHelper.GetDpi(target);var bmp=new RenderTargetBitmap(Math.Max(1,(int)Math.Ceiling(target.ActualWidth*dpi.DpiScaleX)),Math.Max(1,(int)Math.Ceiling(target.ActualHeight*dpi.DpiScaleY)),dpi.PixelsPerInchX,dpi.PixelsPerInchY,PixelFormats.Pbgra32);var background=new DrawingVisual();using(var drawing=background.RenderOpen())drawing.DrawRectangle(window.Background??Brushes.Transparent,null,new Rect(0,0,target.ActualWidth,target.ActualHeight));bmp.Render(background);bmp.Render(target);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bmp));using var file=File.Create(path);encoder.Save(file);}
}
